import sys

def main():
    input_data = sys.stdin.read().split()
    idx = 0

    if idx >= len(input_data):
        return

    N = int(input_data[idx])
    idx += 1

    adj = []
    for i in range(N):
        row = []
        for j in range(N):
            val = int(input_data[idx])
            idx += 1
            row.append(val)
        adj.append(row)

    M = int(input_data[idx])
    idx += 1

    queries = []
    for _ in range(M):
        k = int(input_data[idx])
        idx += 1
        x = int(input_data[idx])
        idx += 1
        queries.append((k, x))

    def mat_mul(A, B, size):
        C = [[0] * size for _ in range(size)]
        for i in range(size):
            for k_idx in range(size):
                if A[i][k_idx]:
                    for j in range(size):
                        if B[k_idx][j]:
                            C[i][j] = 1
        return C

    def mat_pow(A, p, size):
        result = [[0] * size for _ in range(size)]
        for r in range(size):
            result[r][r] = 1

        base = [row[:] for row in A]

        while p > 0:
            if p % 2 == 1:
                result = mat_mul(result, base, size)
            base = mat_mul(base, base, size)
            p //= 2

        return result

    for k, x in queries:
        if k == 0:
            print(0)
            print(-1)
            continue

        power_matrix = mat_pow(adj, k, N)

        start_idx = x - 1
        reachable = []

        for target_idx in range(N):
            if power_matrix[start_idx][target_idx]:
                reachable.append(target_idx + 1)

        reachable.sort()

        if not reachable:
            print(0)
            print(-1)
        else:
            print(len(reachable))
            print(*(reachable))

if __name__ == "__main__":
    main()
